-- Official ETS free sample (TOEIC Sample Form ST-05, ets.org) with ETS answer keys.
-- Source: https://www.ets.org/toeic/test-takers/prepare.html (free Sample Tests PDF).
-- Graphic-based items (Q43, Q82) and incomplete ad texts are excluded.
-- Display shuffles answers; grading maps back, so keys below stay authoritative.

-- Part 2 (ids 500-503)
INSERT INTO toeic_questions (id, part, section, prompt, choices, answer, explanation, grammar_tag, topic, transcript, audio_text) VALUES
(500, 2, 'listening', 'Where''s the new fax machine?', '["Next to the water fountain.", "I''ll send a fax tomorrow.", "By Wednesday."]', 0, 'Hỏi where → đáp án địa điểm. (Đáp án ETS: A)', 'wh-question', 'ets', 'Where''s the new fax machine? Next to the water fountain.', 'Where''s the new fax machine? A. Next to the water fountain. B. I will send a fax tomorrow. C. By Wednesday.'),
(501, 2, 'listening', 'How well does Thomas play the violin?', '["Sure, I really like it.", "Oh, he''s a professional.", "I''ll turn down the volume."]', 1, 'Hỏi mức độ giỏi → "he''s a professional". (Đáp án ETS: B)', 'wh-question', 'ets', 'How well does Thomas play the violin? Oh, he is a professional.', 'How well does Thomas play the violin? A. Sure, I really like it. B. Oh, he is a professional. C. I will turn down the volume.'),
(502, 2, 'listening', 'Martin, are you driving to the client meeting?', '["Oh, would you like a ride?", "Nice to meet you, too.", "I thought it went well!"]', 0, 'Hỏi có lái xe không → mời đi nhờ "would you like a ride?". (Đáp án ETS: A)', 'yes-no', 'ets', 'Martin, are you driving to the client meeting? Oh, would you like a ride?', 'Martin, are you driving to the client meeting? A. Oh, would you like a ride? B. Nice to meet you, too. C. I thought it went well!'),
(503, 2, 'listening', 'Mariko announced that she''s retiring in April.', '["How many did you count?", "I''m not tired at all.", "Right, she''s been here twenty-five years."]', 2, 'Tin nghỉ hưu sau 25 năm → "she''s been here twenty-five years". (Đáp án ETS: C)', 'statement', 'ets', 'Mariko announced that she is retiring in April. Right, she has been here twenty-five years.', 'Mariko announced that she is retiring in April. A. How many did you count? B. I am not tired at all. C. Right, she has been here twenty-five years.')
ON CONFLICT (id) DO NOTHING;

-- Part 3, conv 1: coffee machine (ids 504-506, passage 701)
INSERT INTO toeic_questions (id, part, section, prompt, choices, answer, explanation, grammar_tag, topic, passage_id, transcript, audio_text) VALUES
(504, 3, 'listening', 'Why is the woman calling?', '["To cancel an order", "To complain about a product", "To redeem a gift card", "To renew a warranty"]', 1, 'Máy pha cà phê hỏng sớm → phàn nàn sản phẩm. (Đáp án ETS: B)', 'main-idea', 'ets', 701, 'Woman: Hello. I am calling about a coffee machine I purchased from your website. It stopped working even though I have not had it for very long. I expected it to last much longer than this.\nMan: Oh, I am sorry to hear that. Our warranty covers products for up to a year. Do you know when you bought it?\nWoman: I have had it for a little over a year, so the warranty has probably just expired. This is so disappointing.\nMan: Well, I will tell you what we can do. Although we can not replace it, since you are a valued customer I can offer you a coupon for forty percent off your next purchase.', 'Woman: Hello. I am calling about a coffee machine I purchased from your website. It stopped working even though I have not had it for very long. Man: Our warranty covers products for up to a year. Do you know when you bought it? Woman: I have had it for a little over a year. Man: I can offer you a coupon for forty percent off your next purchase.'),
(505, 3, 'listening', 'What does the man ask the woman about?', '["A model name", "A brand of coffee", "A catalog number", "A date of purchase"]', 3, '"Do you know when you bought it?" → ngày mua. (Đáp án ETS: D)', 'detail', 'ets', 701, 'Woman: Hello. I am calling about a coffee machine I purchased from your website. It stopped working even though I have not had it for very long. I expected it to last much longer than this.\nMan: Oh, I am sorry to hear that. Our warranty covers products for up to a year. Do you know when you bought it?\nWoman: I have had it for a little over a year, so the warranty has probably just expired. This is so disappointing.\nMan: Well, I will tell you what we can do. Although we can not replace it, since you are a valued customer I can offer you a coupon for forty percent off your next purchase.', 'Woman: Hello. I am calling about a coffee machine I purchased from your website. It stopped working even though I have not had it for very long. Man: Our warranty covers products for up to a year. Do you know when you bought it? Woman: I have had it for a little over a year. Man: I can offer you a coupon for forty percent off your next purchase.'),
(506, 3, 'listening', 'What does the man offer to do?', '["Provide a discount", "Send a free sample", "Extend a warranty", "Issue a refund"]', 0, 'Coupon giảm 40% = provide a discount. (Đáp án ETS: A)', 'detail', 'ets', 701, 'Woman: Hello. I am calling about a coffee machine I purchased from your website. It stopped working even though I have not had it for very long. I expected it to last much longer than this.\nMan: Oh, I am sorry to hear that. Our warranty covers products for up to a year. Do you know when you bought it?\nWoman: I have had it for a little over a year, so the warranty has probably just expired. This is so disappointing.\nMan: Well, I will tell you what we can do. Although we can not replace it, since you are a valued customer I can offer you a coupon for forty percent off your next purchase.', 'Woman: Hello. I am calling about a coffee machine I purchased from your website. It stopped working even though I have not had it for very long. Man: Our warranty covers products for up to a year. Do you know when you bought it? Woman: I have had it for a little over a year. Man: I can offer you a coupon for forty percent off your next purchase.'),
-- Part 3, conv 2: hotel shift (ids 507-509, passage 702)
(507, 3, 'listening', 'Where do the speakers work?', '["At a hotel", "At a department store", "At a restaurant", "At a call center"]', 0, 'Làm lễ tân khách sạn (front desk). (Đáp án ETS: A)', 'main-idea', 'ets', 702, 'Man: Oh, hi Yolanda — I am surprised to see you at the front desk this late. Do not you usually work at the hotel in the morning?\nWoman: Actually, I am going to be working the evening shift for a while; I am covering for a front-desk supervisor who was just promoted, but only until the hotel hires a permanent replacement.\nMan: Oh, so there is a front-desk supervisor position open? I have been looking for a chance to take on a managerial role. Are they still accepting applications?\nWoman: Yes, and if you do not mind working evening hours, I think you have a good chance at the job. I would contact the manager right now, though — she is starting interviews this week.', 'Man: Oh, hi Yolanda, surprised to see you at the front desk this late? Woman: Actually, I am working the evening shift, covering for a supervisor who was promoted. Man: So there is a supervisor position open? Are they accepting applications? Woman: Yes, and evening hours give you a good chance. Contact the manager now, interviews start this week.'),
(508, 3, 'listening', 'What does the man ask about?', '["How many people have applied for a promotion", "If a manager is in the lobby", "Whether a position is available", "When new shifts will be assigned"]', 2, 'Hỏi vị trí supervisor còn tuyển không. (Đáp án ETS: C)', 'detail', 'ets', 702, 'Man: Oh, hi Yolanda — I am surprised to see you at the front desk this late. Do not you usually work at the hotel in the morning?\nWoman: Actually, I am going to be working the evening shift for a while; I am covering for a front-desk supervisor who was just promoted, but only until the hotel hires a permanent replacement.\nMan: Oh, so there is a front-desk supervisor position open? I have been looking for a chance to take on a managerial role. Are they still accepting applications?\nWoman: Yes, and if you do not mind working evening hours, I think you have a good chance at the job. I would contact the manager right now, though — she is starting interviews this week.', 'Man: Oh, hi Yolanda, surprised to see you at the front desk this late? Woman: Actually, I am working the evening shift, covering for a supervisor who was promoted. Man: So there is a supervisor position open? Are they accepting applications? Woman: Yes, and evening hours give you a good chance. Contact the manager now, interviews start this week.'),
(509, 3, 'listening', 'What does the woman say the man should be prepared to do?', '["Handle customer complaints", "Work within a budget", "Get to know local clients", "Work evening hours"]', 3, '"...if you do not mind working evening hours...". (Đáp án ETS: D)', 'detail', 'ets', 702, 'Man: Oh, hi Yolanda — I am surprised to see you at the front desk this late. Do not you usually work at the hotel in the morning?\nWoman: Actually, I am going to be working the evening shift for a while; I am covering for a front-desk supervisor who was just promoted, but only until the hotel hires a permanent replacement.\nMan: Oh, so there is a front-desk supervisor position open? I have been looking for a chance to take on a managerial role. Are they still accepting applications?\nWoman: Yes, and if you do not mind working evening hours, I think you have a good chance at the job. I would contact the manager right now, though — she is starting interviews this week.', 'Man: Oh, hi Yolanda, surprised to see you at the front desk this late? Woman: Actually, I am working the evening shift, covering for a supervisor who was promoted. Man: So there is a supervisor position open? Are they accepting applications? Woman: Yes, and evening hours give you a good chance. Contact the manager now, interviews start this week.'),
-- Part 3, conv 3: office expansion (ids 510-512, passage 703)
(510, 3, 'listening', 'What is the conversation mainly about?', '["An enlargement of office space", "A move into a new market", "An increase in staff numbers", "A change in company leadership"]', 0, 'Mở rộng văn phòng tầng trên. (Đáp án ETS: A)', 'main-idea', 'ets', 703, 'Man: Have you two taken a look at the progress they have made upstairs on the office expansion? It looks great!\nWoman: I know! I can not believe it! And the offices up there have amazing views of the city.\nMan: I wonder which division will move up there when it is finished.\nWoman: I heard it is the research department.\nMan: Ah, because they have the most people.\nWoman: Probably. I would love to have an office on that floor, though.\nMan: Yeah. Well, the company must be making good money if they are adding that space!', 'Man: Have you seen the office expansion upstairs? It looks great! Woman: I know! I can not believe it! Amazing city views. Man: Which division moves up there? Woman: The research department, they have the most people. Man: The company must be making good money!'),
(511, 3, 'listening', 'Why does the woman say, "I can''t believe it"?', '["She strongly disagrees.", "She would like an explanation.", "She feels disappointed.", "She is happily surprised."]', 3, 'Ngạc nhiên thích thú trước view đẹp. (Đáp án ETS: D)', 'detail', 'ets', 703, 'Man: Have you two taken a look at the progress they have made upstairs on the office expansion? It looks great!\nWoman: I know! I can not believe it! And the offices up there have amazing views of the city.\nMan: I wonder which division will move up there when it is finished.\nWoman: I heard it is the research department.\nMan: Ah, because they have the most people.\nWoman: Probably. I would love to have an office on that floor, though.\nMan: Yeah. Well, the company must be making good money if they are adding that space!', 'Man: Have you seen the office expansion upstairs? It looks great! Woman: I know! I can not believe it! Amazing city views. Man: Which division moves up there? Woman: The research department, they have the most people. Man: The company must be making good money!'),
(512, 3, 'listening', 'What do the men imply about the company?', '["It was recently founded.", "It is planning to adjust salaries.", "It is in a good financial situation.", "It has offices in other countries."]', 2, '"...must be making good money...". (Đáp án ETS: C)', 'detail', 'ets', 703, 'Man: Have you two taken a look at the progress they have made upstairs on the office expansion? It looks great!\nWoman: I know! I can not believe it! And the offices up there have amazing views of the city.\nMan: I wonder which division will move up there when it is finished.\nWoman: I heard it is the research department.\nMan: Ah, because they have the most people.\nWoman: Probably. I would love to have an office on that floor, though.\nMan: Yeah. Well, the company must be making good money if they are adding that space!', 'Man: Have you seen the office expansion upstairs? It looks great! Woman: I know! I can not believe it! Amazing city views. Man: Which division moves up there? Woman: The research department, they have the most people. Man: The company must be making good money!'),
-- Part 3, conv 4: laptop order (ids 513-514, passage 704)
(513, 3, 'listening', 'What does the woman ask the man to do?', '["Order some equipment", "Find a new vendor", "Repair a laptop", "Contact a job candidate"]', 0, 'Nhờ đặt laptop + màn hình. (Đáp án ETS: A)', 'main-idea', 'ets', 704, 'Woman: Larry, we have a new graphic designer starting next month and we will need to set her up with a laptop and extra monitor. Can you place orders for those?\nMan: Sure. You know our vendor has raised their prices, right?\nWoman: Really?\nMan: Yes. I just looked at the catalog a few minutes ago, and their current models are more expensive.\nWoman: Right. Well, our budget per work area is $1,000 maximum. So let us order the system with the largest screen that falls within that price.\nMan: OK. I will take a look at the prices again and place the order.', 'Woman: Larry, we need a laptop and monitor for our new designer. Can you order them? Man: Sure. Our vendor raised prices. The models cost more now. Woman: Our budget is $1,000 maximum. Order the largest screen within that price. Man: OK, I will place the order.'),
(514, 3, 'listening', 'What problem does the man mention?', '["A designer has left the company.", "A supplier has increased its prices.", "A computer model has been discontinued.", "A departmental budget has been reduced."]', 1, '"...vendor has raised their prices...". (Đáp án ETS: B)', 'detail', 'ets', 704, 'Woman: Larry, we have a new graphic designer starting next month and we will need to set her up with a laptop and extra monitor. Can you place orders for those?\nMan: Sure. You know our vendor has raised their prices, right?\nWoman: Really?\nMan: Yes. I just looked at the catalog a few minutes ago, and their current models are more expensive.\nWoman: Right. Well, our budget per work area is $1,000 maximum. So let us order the system with the largest screen that falls within that price.\nMan: OK. I will take a look at the prices again and place the order.', 'Woman: Larry, we need a laptop and monitor for our new designer. Can you order them? Man: Sure. Our vendor raised prices. The models cost more now. Woman: Our budget is $1,000 maximum. Order the largest screen within that price. Man: OK, I will place the order.')
ON CONFLICT (id) DO NOTHING;

-- Part 4, talk 1: car repair (ids 515-517, passage 705)
INSERT INTO toeic_questions (id, part, section, prompt, choices, answer, explanation, grammar_tag, topic, passage_id, transcript, audio_text) VALUES
(515, 4, 'listening', 'What does the speaker say about the repair?', '["It is not required.", "It has been finished early.", "It will be inexpensive.", "It is covered by a warranty."]', 1, 'Lấy được linh kiện sớm nên sửa xong sớm. (Đáp án ETS: B)', 'detail', 'ets', 705, 'Hello Mr. Lee, this is Thomas from BKS Auto Shop calling with some information about your car repair. I know we told you that it would take until next week to get the part we ordered, but we got the part early, and I was able to finish the repair. We are going to be closing for the day in a few minutes, but you are welcome to come get your car anytime tomorrow. If you need a ride to the shop tomorrow, let me know, and I can arrange one for you.', 'Hello Mr. Lee, this is Thomas from BKS Auto Shop calling with some information about your car repair. I know we told you that it would take until next week to get the part we ordered, but we got the part early, and I was able to finish the repair. You are welcome to come get your car anytime tomorrow. If you need a ride to the shop tomorrow, let me know, and I can arrange one for you.'),
(516, 4, 'listening', 'When can the listener pick up his car?', '["Today", "Tomorrow", "Next week", "In two weeks"]', 1, '"...come get your car anytime tomorrow". (Đáp án ETS: B)', 'detail', 'ets', 705, 'Hello Mr. Lee, this is Thomas from BKS Auto Shop calling with some information about your car repair. I know we told you that it would take until next week to get the part we ordered, but we got the part early, and I was able to finish the repair. We are going to be closing for the day in a few minutes, but you are welcome to come get your car anytime tomorrow. If you need a ride to the shop tomorrow, let me know, and I can arrange one for you.', 'Hello Mr. Lee, this is Thomas from BKS Auto Shop calling with some information about your car repair. I know we told you that it would take until next week to get the part we ordered, but we got the part early, and I was able to finish the repair. You are welcome to come get your car anytime tomorrow. If you need a ride to the shop tomorrow, let me know, and I can arrange one for you.'),
(517, 4, 'listening', 'What does the speaker offer to do?', '["Look for a used part", "Refund the cost of a charge", "Send an invoice", "Arrange a ride"]', 3, '"...I can arrange one [a ride] for you". (Đáp án ETS: D)', 'detail', 'ets', 705, 'Hello Mr. Lee, this is Thomas from BKS Auto Shop calling with some information about your car repair. I know we told you that it would take until next week to get the part we ordered, but we got the part early, and I was able to finish the repair. We are going to be closing for the day in a few minutes, but you are welcome to come get your car anytime tomorrow. If you need a ride to the shop tomorrow, let me know, and I can arrange one for you.', 'Hello Mr. Lee, this is Thomas from BKS Auto Shop calling with some information about your car repair. I know we told you that it would take until next week to get the part we ordered, but we got the part early, and I was able to finish the repair. You are welcome to come get your car anytime tomorrow. If you need a ride to the shop tomorrow, let me know, and I can arrange one for you.'),
-- Part 4, talk 2: restaurant (ids 518-520, passage 706)
(518, 4, 'listening', 'What kind of business does the speaker work for?', '["A restaurant", "A supermarket", "A furniture store", "A fitness center"]', 0, 'Phục vụ món ăn, bàn khách → nhà hàng. (Đáp án ETS: A)', 'main-idea', 'ets', 706, 'OK, before you start serving food, I want to let you know that the restaurant is a bit understaffed tonight. Tamara called me this afternoon to let me know that she has a cold. So I am asking each of you to be in charge of one extra table tonight. Please also remember to tell each table of guests about our new menu special — it is a rice dish with assorted grilled vegetables. I think it will be very popular because many of our customers have been asking for more vegetarian options. That is all for tonight.', 'OK, before you start serving food, I want to let you know that the restaurant is a bit understaffed tonight. Tamara called me this afternoon to let me know that she has a cold. So I am asking each of you to be in charge of one extra table tonight. Please also remember to tell each table of guests about our new menu special. That is all for tonight.'),
(519, 4, 'listening', 'Why does the speaker assign extra work to the listeners?', '["A deadline is approaching.", "A staff member is unwell.", "Many customers are expected.", "Equipment needs to be unpacked."]', 1, 'Tamara bị cảm (a cold) → thiếu người. (Đáp án ETS: B)', 'detail', 'ets', 706, 'OK, before you start serving food, I want to let you know that the restaurant is a bit understaffed tonight. Tamara called me this afternoon to let me know that she has a cold. So I am asking each of you to be in charge of one extra table tonight. Please also remember to tell each table of guests about our new menu special — it is a rice dish with assorted grilled vegetables. I think it will be very popular because many of our customers have been asking for more vegetarian options. That is all for tonight.', 'OK, before you start serving food, I want to let you know that the restaurant is a bit understaffed tonight. Tamara called me this afternoon to let me know that she has a cold. So I am asking each of you to be in charge of one extra table tonight. Please also remember to tell each table of guests about our new menu special. That is all for tonight.'),
(520, 4, 'listening', 'What does the speaker ask listeners to tell customers about?', '["New business hours", "Discount cards", "A special dish", "A holiday sale"]', 2, 'Món đặc biệt mới (rice dish). (Đáp án ETS: C)', 'detail', 'ets', 706, 'OK, before you start serving food, I want to let you know that the restaurant is a bit understaffed tonight. Tamara called me this afternoon to let me know that she has a cold. So I am asking each of you to be in charge of one extra table tonight. Please also remember to tell each table of guests about our new menu special — it is a rice dish with assorted grilled vegetables. I think it will be very popular because many of our customers have been asking for more vegetarian options. That is all for tonight.', 'OK, before you start serving food, I want to let you know that the restaurant is a bit understaffed tonight. Tamara called me this afternoon to let me know that she has a cold. So I am asking each of you to be in charge of one extra table tonight. Please also remember to tell each table of guests about our new menu special. That is all for tonight.'),
-- Part 4, talk 3: Torland meeting (ids 521-523, passage 707)
(521, 4, 'listening', 'What bothers the man about Torland Advertising?', '["Their failure to meet deadlines", "Their problems with staffing", "Their request to revise a contract", "Their focus on cost cutting"]', 3, 'Họ chỉ chăm cắt chi phí thay vì chất lượng. (Đáp án ETS: D)', 'main-idea', 'ets', 707, 'So I called this meeting to discuss our contract with Torland Advertising and to decide whether we should continue to use them to develop our radio advertising materials. I had a discussion with their people yesterday and I have to say, I am a little concerned. They seem much more focused on cutting their costs than they are on providing good quality advertising for us. Here is the thing. If we decide to end this business relationship, we will need to pay them for anything they have already developed. Please take a minute to look at this contract with me. You will see that is part of the agreement we made.', 'So I called this meeting to discuss our contract with Torland Advertising. They seem much more focused on cutting their costs than they are on providing good quality advertising for us. Here is the thing. If we decide to end this business relationship, we will need to pay them for anything they have already developed. Please take a minute to look at this contract with me.'),
(522, 4, 'listening', 'What does the man mean when he says, "Here''s the thing"?', '["He will demonstrate a product.", "He has forgotten a word.", "He has found what he was looking for.", "He will introduce a point to consider."]', 3, '"Here is the thing" = sắp nêu ý cần cân nhắc. (Đáp án ETS: D)', 'vocabulary', 'ets', 707, 'So I called this meeting to discuss our contract with Torland Advertising and to decide whether we should continue to use them to develop our radio advertising materials. I had a discussion with their people yesterday and I have to say, I am a little concerned. They seem much more focused on cutting their costs than they are on providing good quality advertising for us. Here is the thing. If we decide to end this business relationship, we will need to pay them for anything they have already developed. Please take a minute to look at this contract with me. You will see that is part of the agreement we made.', 'So I called this meeting to discuss our contract with Torland Advertising. They seem much more focused on cutting their costs than they are on providing good quality advertising for us. Here is the thing. If we decide to end this business relationship, we will need to pay them for anything they have already developed. Please take a minute to look at this contract with me.'),
(523, 4, 'listening', 'What are the listeners asked to look at?', '["A design idea", "A business contract", "An advertisement", "A budget"]', 1, '"...take a minute to look at this contract...". (Đáp án ETS: B)', 'detail', 'ets', 707, 'So I called this meeting to discuss our contract with Torland Advertising and to decide whether we should continue to use them to develop our radio advertising materials. I had a discussion with their people yesterday and I have to say, I am a little concerned. They seem much more focused on cutting their costs than they are on providing good quality advertising for us. Here is the thing. If we decide to end this business relationship, we will need to pay them for anything they have already developed. Please take a minute to look at this contract with me. You will see that is part of the agreement we made.', 'So I called this meeting to discuss our contract with Torland Advertising. They seem much more focused on cutting their costs than they are on providing good quality advertising for us. Here is the thing. If we decide to end this business relationship, we will need to pay them for anything they have already developed. Please take a minute to look at this contract with me.'),
-- Part 4, talk 4: seminar (ids 524-525, passage 708)
(524, 4, 'listening', 'Where most likely is the speaker?', '["At an award ceremony", "At a musical performance", "At a retirement celebration", "At a training seminar"]', 3, 'Hội thảo buổi chiều, có giờ nghỉ. (Đáp án ETS: D)', 'main-idea', 'ets', 708, 'We are happy to see you all at this seminar this afternoon — we have a lot of useful information to cover. But before we start, a few administrative details. There will be one break, half way through the afternoon. You can leave your laptops here if you leave the room — there will always be someone in here — but do keep your money and phones or other small electronic devices with you. Do not leave them at the tables. And please note that there is an error in your printed program: there will be a change — a switch — in times for the last two presenters. Ms. Ohta has to leave a little early today.', 'We are happy to see you all at this seminar this afternoon. There will be one break, half way through the afternoon. You can leave your laptops here if you leave the room. But do keep your money and phones with you. And please note that there is an error in your printed program: there will be a change in times for the last two presenters.'),
(525, 4, 'listening', 'What are listeners asked to do?', '["Stay seated during the break", "Carry their valuables with them", "Return any borrowed equipment", "Share printed programs with others"]', 1, 'Giữ tiền/điện thoại theo người. (Đáp án ETS: B)', 'detail', 'ets', 708, 'We are happy to see you all at this seminar this afternoon — we have a lot of useful information to cover. But before we start, a few administrative details. There will be one break, half way through the afternoon. You can leave your laptops here if you leave the room — there will always be someone in here — but do keep your money and phones or other small electronic devices with you. Do not leave them at the tables. And please note that there is an error in your printed program: there will be a change — a switch — in times for the last two presenters. Ms. Ohta has to leave a little early today.', 'We are happy to see you all at this seminar this afternoon. There will be one break, half way through the afternoon. You can leave your laptops here if you leave the room. But do keep your money and phones with you. And please note that there is an error in your printed program: there will be a change in times for the last two presenters.')
ON CONFLICT (id) DO NOTHING;

-- Part 5 (ids 526-530)
INSERT INTO toeic_questions (id, part, section, prompt, choices, answer, explanation, grammar_tag, topic) VALUES
(526, 5, 'reading', 'Customer reviews indicate that many modern mobile devices are often unnecessarily -------.', '["complication", "complicates", "complicate", "complicated"]', 3, 'Cần tính từ sau trạng từ "unnecessarily" → complicated. (Đáp án ETS: D)', 'word-forms', 'ets'),
(527, 5, 'reading', 'Jamal Nawzad has received top performance reviews ------- he joined the sales department two years ago.', '["despite", "except", "since", "during"]', 2, '"Since + mốc quá khứ" (two years ago). (Đáp án ETS: C)', 'prepositions', 'ets'),
(528, 5, 'reading', 'Gyeon Corporation''s continuing education policy states that ------- learning new skills enhances creativity and focus.', '["regular", "regularity", "regulate", "regularly"]', 3, 'Cần trạng từ bổ nghĩa "learning" → regularly. (Đáp án ETS: D)', 'word-forms', 'ets'),
(529, 5, 'reading', 'Among ------- recognized at the company awards ceremony were senior business analyst Natalie Obi and sales associate Peter Comeau.', '["who", "whose", "they", "those"]', 3, 'Đại từ thay nhóm người được vinh danh → those. (Đáp án ETS: D)', 'pronouns', 'ets'),
(530, 5, 'reading', 'All clothing sold in Develyn''s Boutique is made from natural materials and contains no ------- dyes.', '["immediate", "synthetic", "reasonable", "assumed"]', 1, 'Trái nghĩa "natural" → synthetic (tổng hợp). (Đáp án ETS: B)', 'word-forms', 'ets')
ON CONFLICT (id) DO NOTHING;

-- Part 6: Pak Designs email (ids 531-534, passage 709)
INSERT INTO toeic_questions (id, part, section, prompt, choices, answer, explanation, grammar_tag, topic, passage_id, passage_text) VALUES
(531, 6, 'reading', 'In the coming weeks, we will be organizing several training sessions for ------- employees.', '["interest", "interests", "interested", "interesting"]', 2, 'Cần tính từ (nhân viên được quan tâm) → interested. (Đáp án ETS: C)', 'word-forms', 'ets', 709, 'To: Project Leads\nFrom: James Pak\nSubject: Training Courses\n\nTo all Pak Designs project leaders:\n\nIn the coming weeks, we will be organizing several training sessions for ___(531) employees. At Pak Designs, we believe that with the proper help and support from our senior project leaders, less experienced staff can quickly ___(532) a deep understanding of the design process. ___(533), they can improve their ability to communicate effectively across divisions. When employees at all experience levels interact, every employee''s competency level rises and the business overall benefits. For that reason, we are urging experienced project leaders to attend each one of the interactive seminars that will be held throughout the coming month. ___(534).\n\nThank you for your support.\nJames Pak\nPak Designs'),
(532, 6, 'reading', 'Less experienced staff can quickly ------- a deep understanding of the design process.', '["develop", "raise", "open", "complete"]', 0, '"Develop an understanding" (phát triển hiểu biết). (Đáp án ETS: A)', 'vocabulary', 'ets', 709, 'To: Project Leads\nFrom: James Pak\nSubject: Training Courses\n\nTo all Pak Designs project leaders:\n\nIn the coming weeks, we will be organizing several training sessions for ___(531) employees. At Pak Designs, we believe that with the proper help and support from our senior project leaders, less experienced staff can quickly ___(532) a deep understanding of the design process. ___(533), they can improve their ability to communicate effectively across divisions. When employees at all experience levels interact, every employee''s competency level rises and the business overall benefits. For that reason, we are urging experienced project leaders to attend each one of the interactive seminars that will be held throughout the coming month. ___(534).\n\nThank you for your support.\nJames Pak\nPak Designs'),
(533, 6, 'reading', '-------, they can improve their ability to communicate effectively across divisions.', '["After all", "For", "Even so", "At the same time"]', 3, '"At the same time" (đồng thời). (Đáp án ETS: D)', 'conjunctions', 'ets', 709, 'To: Project Leads\nFrom: James Pak\nSubject: Training Courses\n\nTo all Pak Designs project leaders:\n\nIn the coming weeks, we will be organizing several training sessions for ___(531) employees. At Pak Designs, we believe that with the proper help and support from our senior project leaders, less experienced staff can quickly ___(532) a deep understanding of the design process. ___(533), they can improve their ability to communicate effectively across divisions. When employees at all experience levels interact, every employee''s competency level rises and the business overall benefits. For that reason, we are urging experienced project leaders to attend each one of the interactive seminars that will be held throughout the coming month. ___(534).\n\nThank you for your support.\nJames Pak\nPak Designs'),
(534, 6, 'reading', 'Which sentence best fits the last blank?', '["Let me explain our plans for on-site staff training.", "We hope that you will strongly consider joining us.", "Today''s training session will be postponed until Monday.", "This is the first in a series of such lectures."]', 1, 'Câu kêu gọi lãnh đạo tham gia → "We hope that you will strongly consider joining us." (Đáp án ETS: B)', 'comprehension', 'ets', 709, 'To: Project Leads\nFrom: James Pak\nSubject: Training Courses\n\nTo all Pak Designs project leaders:\n\nIn the coming weeks, we will be organizing several training sessions for ___(531) employees. At Pak Designs, we believe that with the proper help and support from our senior project leaders, less experienced staff can quickly ___(532) a deep understanding of the design process. ___(533), they can improve their ability to communicate effectively across divisions. When employees at all experience levels interact, every employee''s competency level rises and the business overall benefits. For that reason, we are urging experienced project leaders to attend each one of the interactive seminars that will be held throughout the coming month. ___(534).\n\nThank you for your support.\nJames Pak\nPak Designs')
ON CONFLICT (id) DO NOTHING;

-- Part 7: Salinas article (ids 535-537, passage 710)
INSERT INTO toeic_questions (id, part, section, prompt, choices, answer, explanation, grammar_tag, topic, passage_id, passage_text) VALUES
(535, 7, 'reading', 'What is suggested about Mr. Benavidez?', '["He has hired Salinas Products to distribute his products.", "He has agreed to sell his business to Salinas Products.", "He has recently been hired as an employee of a school.", "He has been chosen to be the new president of Salinas Products."]', 1, 'Ông đồng ý bán chuỗi nhà hàng cho Salinas. (Đáp án ETS: B)', 'comprehension', 'ets', 710, 'On Monday, Salinas Products, a large food distributor based in Mexico City, announced its plans to acquire the Pablo''s restaurant chain. Pablo Benavidez, the chain''s owner, had been considering holding an auction for ownership of the chain. He ultimately made the decision to sell to Salinas without seeking other offers. According to inside sources, Salinas has agreed to keep the restaurant''s name as part of the deal. Mr. Benavidez started the business 40 years ago right after finishing school. He opened a small food stand in his hometown of Cancun. Following that, he opened restaurants in Puerto Vallarta and Veracruz, and there are now over 50 Pablo''s restaurants nationwide.'),
(536, 7, 'reading', 'According to the article, where is Mr. Benavidez from?', '["Cancun", "Veracruz", "Mexico City", "Puerto Vallarta"]', 0, '"...his hometown of Cancun". (Đáp án ETS: A)', 'comprehension', 'ets', 710, 'On Monday, Salinas Products, a large food distributor based in Mexico City, announced its plans to acquire the Pablo''s restaurant chain. Pablo Benavidez, the chain''s owner, had been considering holding an auction for ownership of the chain. He ultimately made the decision to sell to Salinas without seeking other offers. According to inside sources, Salinas has agreed to keep the restaurant''s name as part of the deal. Mr. Benavidez started the business 40 years ago right after finishing school. He opened a small food stand in his hometown of Cancun. Following that, he opened restaurants in Puerto Vallarta and Veracruz, and there are now over 50 Pablo''s restaurants nationwide.'),
(537, 7, 'reading', 'What is indicated about the Pablo''s restaurant chain?', '["It was recently sold in an auction.", "It will soon change its name.", "It was founded 40 years ago.", "It operates in several countries."]', 2, 'Ông mở quán đầu 40 năm trước; tên giữ nguyên; chỉ trong nước. (Đáp án ETS: C)', 'comprehension', 'ets', 710, 'On Monday, Salinas Products, a large food distributor based in Mexico City, announced its plans to acquire the Pablo''s restaurant chain. Pablo Benavidez, the chain''s owner, had been considering holding an auction for ownership of the chain. He ultimately made the decision to sell to Salinas without seeking other offers. According to inside sources, Salinas has agreed to keep the restaurant''s name as part of the deal. Mr. Benavidez started the business 40 years ago right after finishing school. He opened a small food stand in his hometown of Cancun. Following that, he opened restaurants in Puerto Vallarta and Veracruz, and there are now over 50 Pablo''s restaurants nationwide.'),
-- Part 7: library notice (ids 538-541, passage 711)
(538, 7, 'reading', 'What is indicated about advertising space on the Mooringtown Library notice board?', '["It is available at no charge.", "It can be used for any length of time.", "It is open to all area businesses.", "It is intended mainly for sporting events."]', 0, '"...free advertising space..." (miễn phí). (Đáp án ETS: A)', 'comprehension', 'ets', 711, 'Notice Board Space Available to Community Groups\nMooringtown Library is pleased to invite local community groups to use the free advertising space on its new notice board, located outside the front entrance of the library. Space on the board is available for up to four weeks at a time.\nNotices must be approved in advance at the library''s front desk and must meet the following requirements. All content must be suitable for public display. The notice must be written or printed on standard-quality paper with dimensions of either 8.5 in x 11 in or 5.5 in x 8.5 in. The desired start and end date for display should be written in the front bottom right corner. [1] Any notices that do not meet these requirements will not be considered and will be discarded. [2] Submissions are now being accepted at the Mooringtown Library front desk. Please have the actual notice, in the format in which you would like it to appear, with you when you arrive. Within one business day, you will receive a call confirming that your notice has been added to the board. [3] [4]\nMooringtown Library'),
(539, 7, 'reading', 'What is NOT a stated requirement for a notice to be placed on the board?', '["It must meet certain size requirements.", "It must be marked with posting dates.", "It must be reviewed beforehand.", "It must be signed by a librarian."]', 3, 'Không hề nhắc ký tên thủ thư. (Đáp án ETS: D)', 'comprehension', 'ets', 711, 'Notice Board Space Available to Community Groups\nMooringtown Library is pleased to invite local community groups to use the free advertising space on its new notice board, located outside the front entrance of the library. Space on the board is available for up to four weeks at a time.\nNotices must be approved in advance at the library''s front desk and must meet the following requirements. All content must be suitable for public display. The notice must be written or printed on standard-quality paper with dimensions of either 8.5 in x 11 in or 5.5 in x 8.5 in. The desired start and end date for display should be written in the front bottom right corner. [1] Any notices that do not meet these requirements will not be considered and will be discarded. [2] Submissions are now being accepted at the Mooringtown Library front desk. Please have the actual notice, in the format in which you would like it to appear, with you when you arrive. Within one business day, you will receive a call confirming that your notice has been added to the board. [3] [4]\nMooringtown Library'),
(540, 7, 'reading', 'What should an advertiser bring to the library when making a submission?', '["An outline of proposed content", "A final version of the notice", "A completed submission form", "A letter from an organization"]', 1, '"Please have the actual notice... with you". (Đáp án ETS: B)', 'comprehension', 'ets', 711, 'Notice Board Space Available to Community Groups\nMooringtown Library is pleased to invite local community groups to use the free advertising space on its new notice board, located outside the front entrance of the library. Space on the board is available for up to four weeks at a time.\nNotices must be approved in advance at the library''s front desk and must meet the following requirements. All content must be suitable for public display. The notice must be written or printed on standard-quality paper with dimensions of either 8.5 in x 11 in or 5.5 in x 8.5 in. The desired start and end date for display should be written in the front bottom right corner. [1] Any notices that do not meet these requirements will not be considered and will be discarded. [2] Submissions are now being accepted at the Mooringtown Library front desk. Please have the actual notice, in the format in which you would like it to appear, with you when you arrive. Within one business day, you will receive a call confirming that your notice has been added to the board. [3] [4]\nMooringtown Library'),
(541, 7, 'reading', 'Where does the sentence about name and phone number best belong?', '["[1]", "[2]", "[3]", "[4]"]', 0, 'Thông tin liên hệ đặt cuối yêu cầu ([1]). (Đáp án ETS: A)', 'comprehension', 'ets', 711, 'Notice Board Space Available to Community Groups\nMooringtown Library is pleased to invite local community groups to use the free advertising space on its new notice board, located outside the front entrance of the library. Space on the board is available for up to four weeks at a time.\nNotices must be approved in advance at the library''s front desk and must meet the following requirements. All content must be suitable for public display. The notice must be written or printed on standard-quality paper with dimensions of either 8.5 in x 11 in or 5.5 in x 8.5 in. The desired start and end date for display should be written in the front bottom right corner. [1] Any notices that do not meet these requirements will not be considered and will be discarded. [2] Submissions are now being accepted at the Mooringtown Library front desk. Please have the actual notice, in the format in which you would like it to appear, with you when you arrive. Within one business day, you will receive a call confirming that your notice has been added to the board. [3] [4]\nMooringtown Library')
ON CONFLICT (id) DO NOTHING;

